      "name": "Chapter 7: Traditional Societies, Religion, and Culture (West Africa Focus)",
      "image": "https://images.pexels.com/photos/28841748/pexels-photo-28841748.jpeg?auto=compress&cs=tinysrgb&h=650&w=940",
